import csv

with open('gtfs_extract/stop_times.txt', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

print(f'Total stop_times: {len(rows)}')

# Check for times beyond 24:00:00
late_times = []
for r in rows:
    for field in ['arrival_time', 'departure_time']:
        t = r[field]
        if t:
            parts = t.split(':')
            if len(parts) >= 2:
                hours = int(parts[0])
                if hours >= 24:
                    late_times.append((r['trip_id'], r['stop_id'], field, t))
print(f'Times beyond 24:00:00: {len(late_times)}')
for lt in late_times[:10]:
    print(f'  {lt}')
"
